def _prompt_ingredients(prompt):
    lowered = prompt.lower()
    return [(title, display) for tokens, title, display in INGREDIENT_HINTS if any(token in lowered for token in tokens)]

def _prompt_category(prompt, current_key):
    lowered = prompt.lower()
    if any(word in lowered for word in ("бургер", "бургерн", "котлет")): return "burgers"
    if any(word in lowered for word in ("пицц", "пепперони")): return "pizza"
    if any(word in lowered for word in ("десерт", "торт", "тарт", "пирог", "сладк")): return "desserts"
    if any(word in lowered for word in ("чай", "матча", "кофе", "латте", "напиток")): return "eastern_tea" if "чай" in lowered else "drinks"
    if any(word in lowered for word in ("мезе", "хумус", "долм", "закуск")): return "eastern_meze"
    if any(word in lowered for word in ("плов", "манты", "самс", "куырдак")): return "eastern_mains"
    if any(word in lowered for word in ("боул", "поке")): return "bowls"
    if any(word in lowered for word in ("восточ", "мезе", "хумус", "плов", "самс")) and current_key in ("drinks", "mains"):
        return "eastern_tea" if current_key == "drinks" else "eastern_mains"
    if any(word in lowered for word in ("фастфуд", "street food", "навынос")) and current_key in ("drinks", "mains"):
        return "fastfood_snacks"
    return current_key

def generate_items(category, count=3, season="", vibe="", venue="", prompt="", inspiration=False):
    key=CATEGORY_MAP.get(category,"mains")
    if "Восточное кафе" in venue:
        key={"drinks":"eastern_tea","mains":"eastern_mains","desserts":"eastern_desserts"}.get(key,key)
    elif "Крафтовый фастфуд" in venue and key=="drinks":
        key="fastfood_snacks"
    key=_prompt_category(prompt, key)
    dishes=RECIPES.get(key, RECIPES["mains"])
    selected=[KAMI_SPECIAL] if inspiration else random.SystemRandom().sample(dishes,k=min(max(1,count),len(dishes)))
    ingredients=_prompt_ingredients(prompt)
    lowered=prompt.lower()
    category_label=next((label for label, mapped in CATEGORY_MAP.items() if mapped==key), category)
    vibe_note={"Утренний дзен и эстетика":"Утренний дзен и эстетичная подача.","Энергия большого города":"Бодрый городской характер и яркий контраст вкусов.","Романтичный вечер":"Мягкая подача для неспешного романтичного вечера.","Лёгкий ЗОЖ и баланс":"Лёгкий баланс вкуса, текстуры и свежих ингредиентов."}.get(vibe, "")
    result=[]
    for name,desc,price,nutrition in selected:
        if prompt and not inspiration:
            adjective="Острый " if "остр" in lowered else "Осенний " if any(w in lowered for w in ("осен", "тыкв", "корица")) else "Авторский " if "авторск" in lowered else ""
            food="бургер" if key=="burgers" else "десерт" if key in ("desserts","eastern_desserts") else "пицца" if key=="pizza" else "чай" if key in ("eastern_tea",) else "напиток" if key=="drinks" else "боул" if key=="bowls" else "блюдо"
            if ingredients:
                ingr=" и ".join(title for title, _ in ingredients[:3])
                name=f"{adjective}{food.capitalize()} с {ingr}"
                desc += " По вашей идее добавлены " + ", ".join(display for _, display in ingredients[:3]) + "; вкус и подача собраны под ваш запрос."
            elif any(w in lowered for w in ("уют", "романт", "нежн")):
                desc += " Подача мягкая и уютная — для неспешного вечера в любимой кофейне."
            elif prompt:
                desc += " Идея адаптирована под ваш запрос и формат заведения."
            if any(word in lowered for word in ("навынос", "с собой", "takeaway")):
                desc += " Удобная подача навынос — для прогулки или короткого городского перерыва."
            elif any(word in lowered for word in ("романтич", "вечер", "свидан")):
                desc += " Подача рассчитана на неспешный романтичный вечер."
            elif any(word in lowered for word in ("лёгк", "легк", "зож", "баланс")):
                desc += " Лёгкий баланс вкуса и текстуры для бодрого дня."
            if any(word in lowered for word in ("кофейн", "кофейня", "матча-бар")):
                desc += " Создано для уютной кофейни и долгих разговоров за чашкой."
            elif any(word in lowered for word in ("восточ", "нео-восток")):
                desc += " Восточные пряности и щедрая подача в современной городской интерпретации."
            elif any(word in lowered for word in ("фастфуд", "бургерн", "стритфуд")):
                desc += " Яркая, удобная подача для быстрого городского перекуса."
        seasonal=f" Сезонный штрих — {season.lower()}." if season and not inspiration else ""
        desc += seasonal
        if vibe_note:
            desc += " " + vibe_note
        social=f"✨ {name}\n{desc}\n\nЗаходите за своим маленьким удовольствием 🤍\n#Алматы #кофейняалматы #almatycafe #вкусныйалматы"
        result.append({"name":name,"description":desc,"price":price,"nutrition":nutrition,"social_post":social,"category":"Выбор Ками 🤍" if inspiration else category_label,"choice":bool(inspiration)})
    return result

def enrich_with_gemini(items, filters, api_key):
    """Ask Gemini to polish the locally curated items; safely keep the fallback data."""
    prompt = ("Верни только JSON-массив из объектов name,description,price,nutrition,social_post,category. "
              "Сохрани цены и КБЖУ. Пиши изысканно и естественно по-русски, с локальным вайбом Алматы. "
              f"Параметры: {json.dumps(filters, ensure_ascii=False)}. Блюда: {json.dumps(items, ensure_ascii=False)}")
    body = json.dumps({"contents":[{"parts":[{"text":prompt}]}],"generationConfig":{"responseMimeType":"application/json"}}).encode()
    req=urllib.request.Request(f"https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key={api_key}",data=body,headers={"Content-Type":"application/json"},method="POST")
    with urllib.request.urlopen(req, timeout=12) as response:
        answer=json.loads(response.read())['candidates'][0]['content']['parts'][0]['text']
    polished=json.loads(answer)
    return polished if isinstance(polished,list) and polished else items
